INSERT INTO booths (id, location_id, code, name, name_en, publisher, category, area_name, dimensions, open_hours, description, image_url, op_status, is_deleted) VALUES
  ('c5966a62-03fe-4093-ae26-4faa7a102a8b', 'e344f9f5-dc96-4189-a78e-5485c84f8349', 'B-01', 'Gian hàng Nhà Xuất Bản Trẻ', 'Tre Publishing House Booth', 'NXB Trẻ', 'literature', 'Khu A', '3m x 3m', '08:00 - 22:00', 'Không gian ấm cúng với những đầu sách văn học đương đại Việt Nam, sách dịch kinh điển, dòng sách tư tưởng và thiếu niên. Nơi thường xuyên diễn ra các buổi ký tặng sách thân mật cùng tác giả.', 'https://images.unsplash.com/photo-1524995997946-a1c2e315a42f?auto=format&fit=crop&w=800&q=80', 'operational'::booth_op_status, false),
  ('e757df4c-4212-4f50-af7f-bb2c38f6a9cf', '10db7331-20ad-4073-af91-1ccd7e3987c0', 'B-02', 'Gian hàng Nhà Xuất Bản Kim Đồng', 'Kim Dong Publishing House', 'NXB Kim Đồng', 'children', 'Khu A', '3m x 3m', '08:00 - 22:00', 'Điểm dừng chân yêu thích của các gia đình và độc giả trẻ. Trưng bày đầy đủ các bộ truyện tranh huyền thoại, văn học thiếu nhi kinh điển, sách tương tác và kỹ năng sống bổ ích.', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?auto=format&fit=crop&w=800&q=80', 'operational'::booth_op_status, false),
  ('2291365a-10b9-445c-a44b-ad5f0261d2d1', 'a9e00195-fbc3-42e4-a60a-cdb18d961e5b', 'B-03', 'Hiệu sách Nhã Nam', 'Nha Nam Bookstore', 'Nhã Nam', 'literature', 'Khu A', '3m x 3m', '08:00 - 22:00', 'Không gian mang hơi thở châu Âu cổ điển giữa lòng phố sách. Nổi tiếng với các bản dịch chuẩn xác của những giải Nobel văn chương, triết học và các tác phẩm lịch sử kinh điển thế giới.', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?auto=format&fit=crop&w=800&q=80', 'operational'::booth_op_status, false),
  ('6388f756-c9b9-4e73-ae58-1d4d078e82be', 'afa37df7-f49d-4728-a951-abfb72db4790', 'B-04', 'Phương Nam Book Store', 'Phuong Nam Book Pavilion', 'Phương Nam', 'lifestyle', 'Khu A', '3m x 3m', '08:00 - 22:00', 'Trưng bày phong phú sách nghiên cứu văn hóa Sài Gòn - Nam Bộ xưa và nay, kết hợp quầy văn phòng phẩm thủ công, bưu thiếp lưu niệm đặc trưng dành cho du khách quốc tế.', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?auto=format&fit=crop&w=800&q=80', 'operational'::booth_op_status, false),
  ('aa6bd434-33ae-4e7b-aee6-0bfd2e8553c6', '9ea56cd5-504c-485a-a30b-3d4b8b2375eb', 'B-05', 'Thái Hà Books', 'Thai Ha Books', 'Thái Hà', 'history', 'Khu A', '3m x 3m', '08:00 - 21:30', 'Chuyên trang dòng sách nuôi dưỡng tinh thần, lãnh đạo, khởi nghiệp và giáo dục khai phóng. Thường có góc thưởng trà đàm đạo về văn hóa đọc chậm rãi giữa nhịp sống đô thị.', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?auto=format&fit=crop&w=800&q=80', 'operational'::booth_op_status, false),
  ('ee1bade5-6dae-44b5-a453-9b670698d819', '35d794cd-618e-4380-ac04-c486665f0925', 'B-06', 'Cà Phê Sách Bằng Lăng Tím', 'Bang Lang Tim Book Cafe', 'Khu vực dịch vụ văn hóa', 'cafe', 'Khu A', '3m x 3m', '07:30 - 22:30', 'Điểm dừng chân thư thái nằm giữa trung tâm con đường. Du khách vừa đọc những trang sách vừa mua, vừa lắng nghe tiếng chuông Nhà thờ Đức Bà vang lại và ngắm nhìn dòng người tản bộ.', 'https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=800&q=80', 'operational'::booth_op_status, false),
  ('6d2df04d-8992-4959-a787-6fdbf3c55804', 'eca9f427-9189-4548-ad2f-2b33b4f1f179', 'B-07', 'Gian hàng NXB Tổng Hợp TP.HCM', 'HCMC General Publishing House', 'NXB Tổng Hợp TP.HCM', 'history', 'Khu A', '3m x 3m', '08:00 - 22:00', 'Nơi tập hợp những bộ sách nghiên cứu công phu nhất về lịch sử hình thành Sài Gòn - Gia Định, các công trình khảo cứu văn hóa dân gian và hồi ký các nhân chứng lịch sử.', 'https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8?auto=format&fit=crop&w=800&q=80', 'operational'::booth_op_status, false),
  ('88266c1a-e23b-4235-a1da-7652da4b4639', '2a0ec771-a791-4a7b-af72-0d3826c99871', 'B-08', 'First News - Trí Việt', 'First News - Tri Viet', 'First News', 'history', 'Khu A', '3m x 3m', '08:00 - 22:00', 'Gian hàng nổi bật với dòng sách truyền cảm hứng sống đẹp, vượt qua nghịch cảnh, nghệ thuật lãnh đạo và các tác phẩm bản quyền chuyển nhượng quốc tế.', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?auto=format&fit=crop&w=800&q=80', 'operational'::booth_op_status, false),
  ('5b8481d3-dc49-4669-a850-0a21d33d8982', '1dd0b5d5-3651-475a-aab7-aebf6d628273', 'B-09', 'Đinh Tị Books', 'Dinh Ti Books', 'Đinh Tị', 'children', 'Khu A', '3m x 3m', '08:00 - 21:30', 'Gian hàng thiếu nhi đầy màu sắc kỳ diệu với các dòng sách chuyển động, sách lật mở và bộ bách khoa toàn thư trực quan sống động cho lứa tuổi mầm non và tiểu học.', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?auto=format&fit=crop&w=800&q=80', 'operational'::booth_op_status, false),
  ('7fc55ea4-e4c7-46f6-ac99-41aa8a149d42', '0ce1362f-8a1e-4f0e-a42d-8129cc3d0926', 'B-10', 'Alpha Books & Omega Plus', 'Alpha Books & Omega Plus', 'Alpha Books', 'history', 'Khu A', '3m x 3m', '08:00 - 22:00', 'Địa chỉ tin cậy cho giới doanh nhân, nhà quản lý và học giả với các công trình nghiên cứu kinh điển về kinh tế, lịch sử văn minh và tư tưởng thế giới.', 'https://images.unsplash.com/photo-1532012164546-f432f2e3edd3?auto=format&fit=crop&w=800&q=80', 'operational'::booth_op_status, false),
  ('035e284f-91e7-4f0a-ae81-a3dc356c7fef', '92522c68-e53f-4e54-ad29-651d6f89ca79', 'B-11', 'Gian hàng Nhà Xuất Bản Phụ Nữ', 'Women Publishing House Booth', 'NXB Phụ Nữ', 'literature', 'Khu A', '3m x 3m', '08:00 - 21:30', 'Trưng bày các tác phẩm văn học đương đại của các tác giả nữ danh tiếng, cẩm nang nuôi dạy con bằng tình yêu thương và sách sức khỏe tâm lý.', 'https://images.unsplash.com/photo-1491841573634-28140fc7ced7?auto=format&fit=crop&w=800&q=80', 'operational'::booth_op_status, false),
  ('3ceb8da4-e4ba-44aa-a518-707afa32e515', '22848a0d-4a62-4966-acdf-433cedb3a7e2', 'B-12', 'Không Gian Lưu Niệm & Tranh Cổ', 'Saigon Vintage Postcard & Art Pavilion', 'Đường Sách TP.HCM', 'cafe', 'Khu A', '3m x 3m', '08:00 - 22:00', 'Góc dừng chân văn hóa độc đáo dành cho du khách muốn gửi tặng bưu thiếp đóng dấu bưu điện trực tiếp tại Đường Sách và mua các món quà lưu niệm mỹ nghệ mang đậm dấu ấn Việt Nam.', 'https://images.unsplash.com/photo-1513542789411-b6a5d4f31634?auto=format&fit=crop&w=800&q=80', 'operational'::booth_op_status, false),
  ('c0bbb4f8-3380-4eed-aab7-67dbdb33af5b', 'eeef7413-87f1-41e6-af08-e1b450ad3fa8', 'A01', 'Gian A01', 'Gian A01', 'NXB Trẻ', 'Văn học & Nghệ thuật', 'Khu A', '3m x 3m', '08:00 - 22:00', 'Khu trưng bày các tác phẩm văn học chọn lọc.', 'https://images.unsplash.com/photo-1521587760476-6c12a4b040da?auto=format&fit=crop&w=600&q=80', 'operational'::booth_op_status, false),
